mapper.select:
SELECT p.id, p.plan_no, p.status, p.warehouse_id, p.container_order_id, p.container_order_no, p.remark, p.create_time, p.update_time, ch.channel_name, c.customer_name, c.eta, c.total_cbm, c.total_carton_qty, c.total_weight FROM wms_inbound_plan p LEFT JOIN oms_container_order c ON c.id = p.container_order_id AND c.deleted = 0 LEFT JOIN base_channel ch ON ch.id = c.channel_id AND ch.deleted = 0 WHERE p.deleted = 0 AND p.tenant_id = #{bo.tenantId}
AND p.warehouse_id = #{bo.warehouseId}
AND p.container_order_id = #{bo.containerOrderId}
AND p.plan_no LIKE CONCAT('%', #{bo.planNo}, '%')
AND p.status = #{bo.status}
ORDER BY p.create_time DESC
